{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbf8;--muted:#6b6b6b;--accent:#2b7a63;--accent-2:#0f5f4a;--card:#fff;--glass:rgba(255,255,255,0.7)}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#132;line-height:1.45;background:linear-gradient(180deg,var(--bg),#f2f7f4);min-height:100vh}
    header{display:flex;align-items:center;justify-content:space-between;padding:24px 28px;background:var(--card);border-bottom:1px solid rgba(20,20,20,0.04)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    nav a[href$="pricing.html"]{color:var(--accent)}
    main{max-width:980px;margin:28px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center;padding:28px;border-radius:12px;background:linear-gradient(180deg,rgba(43,122,99,0.06),rgba(15,95,74,0.02));box-shadow:0 6px 18px rgba(14,30,24,0.06)}
    .hero h1{margin:0;font-size:1.7rem;color:var(--accent-2)}
    .hero p{margin:6px 0;color:var(--muted)}
    .cta-btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;border:0;font-weight:700;cursor:pointer}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(6,10,8,0.04)}
    .card h3{margin:0 0 8px 0}
    .price{font-size:1.6rem;color:var(--accent-2);font-weight:800}
    .muted{color:var(--muted);font-size:0.95rem}
    .inline{display:flex;gap:10px;align-items:center}
    .small{font-size:0.9rem;color:var(--muted)}
    footer{max-width:980px;margin:36px auto;padding:20px;color:var(--muted);font-size:0.9rem}

    /* inventory */
    .inventory{margin-top:22px;padding:18px;background:linear-gradient(180deg,#fff,rgba(250,255,250,0.4));border-radius:12px}
    .areas{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
    .area label{display:flex;align-items:center;gap:8px;cursor:pointer;padding:8px;border-radius:8px}
    .area input{width:18px;height:18px}
    .agenda{margin-top:14px;padding:12px;border-radius:10px;background:rgba(11,44,36,0.03)}
    .result-header{font-weight:700;color:var(--accent-2)}
    .cadence{font-weight:700;color:var(--accent)}

    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(4,10,8,0.28);display:none;align-items:center;justify-content:center;padding:20px}
    .modal{background:var(--card);max-width:720px;width:100%;border-radius:12px;padding:18px;box-shadow:0 18px 40px rgba(8,20,16,0.18)}
    .modal h4{margin:0 0 8px}
    .modal .controls{display:flex;gap:8px;margin-top:12px}
    .circle{width:86px;height:86px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:linear-gradient(180deg,#fbfff9,#eef7f4);font-weight:700;color:var(--accent-2)}

    /* small */
    .tiny{font-size:0.85rem;color:var(--muted)}
    .linkish{background:none;border:0;color:var(--accent);text-decoration:underline;cursor:pointer;padding:0}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:0.85rem;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Start</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Concerns</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Studio</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <h1>Transparent options for guided, integrative support</h1>
        <p class="muted">Practical session bundles and guided-learning tracks designed for life with responsibilities. No miracle promises—just a clear plan you can try and adjust.</p>
        <div style="margin-top:12px" class="inline">
          <button class="cta-btn" onclick="location.href='book.html'">Reserve a discovery seat</button>
          <button class="linkish" id="open-exercise">Try a 3-minute clarity exercise</button>
        </div>
      </div>
      <div style="text-align:right">
        <div class="small">Need help now?</div>
        <div style="margin-top:8px;font-weight:800">{{PHONE}}</div>
        <div class="tiny" style="margin-top:6px">or <a href="contact.html" style="color:var(--accent)">send a brief note</a></div>
      </div>
    </section>

    <section class="grid" aria-label="rates">
      <div class="card">
        <h3>Intro Insight Session</h3>
        <div class="price">$125</div>
        <div class="muted">60 minutes — comprehensive listening, initial inventory, and focused next steps.</div>
        <div style="margin-top:12px" class="inline">
          <button class="cta-btn" onclick="location.href='book.html?pack=intro'">Reserve</button>
          <button class="linkish" onclick="openInventory()">Run the inventory</button>
        </div>
      </div>

      <div class="card">
        <h3>Care Plan Package</h3>
        <div class="price">$480</div>
        <div class="muted">Four 45-minute sessions across 12 weeks — includes guided practices and check-ins.</div>
        <div style="margin-top:12px" class="inline">
          <button class="cta-btn" onclick="location.href='book.html?pack=package'">Select plan</button>
          <button class="linkish" onclick="openInventory()">Preview agenda</button>
        </div>
      </div>

      <div class="card">
        <h3>Focused Skills Mini</h3>
        <div class="price">$220</div>
        <div class="muted">Two sessions + tailored micro-habit guide — great for one problem area.</div>
        <div style="margin-top:12px" class="inline">
          <button class="cta-btn" onclick="location.href='book.html?pack=mini'">Choose mini</button>
          <button class="linkish" onclick="openInventory()">See typical cadence</button>
        </div>
      </div>
    </section>

    <section class="inventory" id="inventory-widget">
      <h3 style="margin-top:0">Whole-person inventory — quick starter</h3>
      <div class="tiny">Check the areas you'd like support with. You'll get a suggested consultation agenda and a follow-up cadence tailored to what you select.</div>

      <div class="areas" style="margin-top:12px">
        <div class="area"><label><input type="checkbox" value="Sleep"/> Sleep</label></div>
        <div class="area"><label><input type="checkbox" value="Energy"/> Energy & Fatigue</label></div>
        <div class="area"><label><input type="checkbox" value="Mood"/> Mood & Stress</label></div>
        <div class="area"><label><input type="checkbox" value="Gut"/> Digestion</label></div>
        <div class="area"><label><input type="checkbox" value="Movement"/> Movement & Strength</label></div>
        <div class="area"><label><input type="checkbox" value="Relationships"/> Relationships</label></div>
        <div class="area"><label><input type="checkbox" value="Work"/> Work & Boundaries</label></div>
        <div class="area"><label><input type="checkbox" value="Purpose"/> Meaning & Purpose</label></div>
      </div>

      <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
        <button class="cta-btn" onclick="runInventory()">Generate agenda</button>
        <button class="linkish" onclick="clearInventory()">Clear</button>
      </div>

      <div class="agenda" id="agenda-output" style="display:none">
        <div class="result-header">Suggested consultation agenda</div>
        <div id="agenda-list" style="margin-top:8px"></div>
        <div style="margin-top:10px" class="cadence" id="cadence-output"></div>
        <div style="margin-top:10px" class="tiny">You can bring this agenda to your booking or copy it into a message to us.</div>
        <div style="margin-top:8px"><button class="linkish" onclick="copyAgenda()">Copy agenda</button></div>
      </div>
    </section>

    <section style="margin-top:18px" class="card">
      <h4 style="margin:0">Pricing philosophy</h4>
      <p class="muted" style="margin-top:8px">We prefer transparent bundles and clear revisit points rather than open-ended subscriptions. Each option includes a planned set of work and a recommended follow-up cadence based on your inventory and goals.</p>
    </section>

  </main>

  <footer>
    <div>Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>. Pricing subject to change; sessions are educational and supportive — not a substitute for medical care.</div>
  </footer>

  <!-- Modal: guided practice -->
  <div class="modal-backdrop" id="modal" role="dialog" aria-modal="true">
    <div class="modal" id="modal-card">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <h4 id="modal-title">3-minute clarity practice</h4>
        <button onclick="closeModal()" class="linkish">Close</button>
      </div>
      <div id="modal-body" style="margin-top:12px">
        <div style="display:flex;gap:12px;align-items:flex-start">
          <div class="circle" id="timer-display">3:00</div>
          <div style="flex:1">
            <div id="modal-instructions">Choose a short practice to reset focus: breathing, journaling, or intention-setting.</div>
            <div class="controls" style="margin-top:12px">
              <button class="cta-btn" onclick="startPractice('breath')">Breathing</button>
              <button class="cta-btn" onclick="startPractice('journal')">Journaling</button>
              <button class="cta-btn" onclick="startPractice('intention')">Intention</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Inventory logic
    function openInventory(){
      document.getElementById('inventory-widget').scrollIntoView({behavior:'smooth'});
    }
    function clearInventory(){
      document.querySelectorAll('#inventory-widget input[type=checkbox]').forEach(cb=>cb.checked=false);
      document.getElementById('agenda-output').style.display='none';
    }
    function runInventory(){
      const boxes = Array.from(document.querySelectorAll('#inventory-widget input[type=checkbox]'));
      const checked = boxes.filter(b=>b.checked).map(b=>b.value);
      const out = document.getElementById('agenda-list');
      const cadenceEl = document.getElementById('cadence-output');
      out.innerHTML='';
      if(checked.length===0){
        out.innerHTML='<div class="tiny">No areas selected — consider a single-session discovery to broaden intake.</div>';
        cadenceEl.textContent='Suggested cadence: Single 60-minute discovery';
        document.getElementById('agenda-output').style.display='block';
        return;
      }

      // Agenda generation mapping
      const mapping = {
        'Sleep': ['Sleep pattern review, 1-week sleep log review, nighttime routine experiments'],
        'Energy': ['Daily energy mapping, caffeine & meal timing review, micro-renewal practices'],
        'Mood': ['Stress-response mapping, short journaling habit, coping strategies'],
        'Gut': ['Dietary pattern review, simple elimination steps, digestive timing'],
        'Movement': ['Functional movement screen, small strength plan, habit anchors'],
        'Relationships': ['Boundary inventory, communication micro-practices, support mapping'],
        'Work': ['Workload triage, priority-setting practice, rhythm adjustments'],
        'Purpose': ['Values clarification exercise, small experiments to test interest']
      };

      // Create agenda items
      checked.forEach(area=>{
        const li = document.createElement('div');
        li.innerHTML='<strong>'+area+'</strong>: '+(mapping[area]||['Listening and tailored next steps']).join('; ');
        out.appendChild(li);
      });

      // cadence logic: more areas -> more frequent touchpoints initially
      let cadence='';
      if(checked.length<=1) cadence='Recommended cadence: 1-2 sessions monthly until goals settle.';
      else if(checked.length<=3) cadence='Recommended cadence: Biweekly work for 6-8 weeks, then reassess.';
      else cadence='Recommended cadence: Weekly or biweekly initial touchpoints for 8-12 weeks, plus short check-ins.';

      cadenceEl.textContent=cadence;
      document.getElementById('agenda-output').style.display='block';
      // Store as data for copy
      document.getElementById('agenda-output').dataset.agenda = JSON.stringify({areas:checked,agenda:out.innerText,cadence:cadence});
    }
    function copyAgenda(){
      const data = document.getElementById('agenda-output').dataset.agenda;
      if(!data){ alert('Generate an agenda first.'); return; }
      const obj = JSON.parse(data);
      const text = 'Agenda for: '+obj.areas.join(', ')+'\n\n'+obj.agenda+'\n\n'+obj.cadence;
      navigator.clipboard?.writeText(text).then(()=>alert('Agenda copied to clipboard.'))
        .catch(()=>{ prompt('Copy this text:', text); });
    }

    // Modal guided practice
    const modal = document.getElementById('modal');
    const timerDisplay = document.getElementById('timer-display');
    let timerId=null, remaining=180;

    document.getElementById('open-exercise').addEventListener('click',()=>{ modal.style.display='flex'; resetModal(); });
    function closeModal(){ modal.style.display='none'; stopTimer(); }
    function resetModal(){ document.getElementById('modal-title').textContent='3-minute clarity practice'; document.getElementById('modal-instructions').textContent='Choose a short practice to reset focus: breathing, journaling, or intention-setting.'; timerDisplay.textContent='3:00'; remaining=180; }

    function startPractice(type){ stopTimer(); remaining=180; updateTime(); document.getElementById('modal-title').textContent = {breath:'Breathing practice',journal:'Guided journaling',intention:'Intention-setting'}[type];
      if(type==='breath'){ startBreathing(); }
      else if(type==='journal'){ startJournal(); }
      else { startIntention(); }
    }
    function startBreathing(){
      document.getElementById('modal-instructions').textContent='Find a comfortable seated position. We will guide a paced breathe: inhale 4s, hold 3s, exhale 5s. Follow the circle.';
      let phase=0; // 0 inhale,1 hold,2 exhale
      let cycle=[4,3,5];
      updateTime();
      timerId = setInterval(()=>{
        if(remaining<=0){ stopTimer(); document.getElementById('modal-instructions').textContent='Practice complete. Notice how you feel.'; return; }
        const step = cycle[phase];
        const phaseStart = Math.floor(remaining% (cycle.reduce((a,b)=>a+b)));
        // simple animation: change background of circle
        document.querySelector('.circle').style.transform = 'scale('+(1+0.03*Math.sin(Date.now()/200))+')';
        remaining--; updateTime();
        // change phase roughly: rotate every few seconds
        if(Math.random()<0.03) phase=(phase+1)%3;
      },1000);
    }
    function startJournal(){
      document.getElementById('modal-instructions').innerHTML = 'Prompt: "What is a small next step I can try this week?"\n\nType your response below. You have three minutes.';
      // add textarea
      const body = document.getElementById('modal-body');
      const ta = document.createElement('textarea');
      ta.style.width='100%'; ta.style.height='100px'; ta.id='journal-text'; ta.placeholder='Write for a few minutes...';
      if(!document.getElementById('journal-text')) body.appendChild(ta);
      updateTime();
      timerId = setInterval(()=>{ if(remaining<=0){ stopTimer(); document.getElementById('modal-instructions').textContent='Time is up — thank you. Copy or save your note.'; return; } remaining--; updateTime(); },1000);
    }
    function startIntention(){
      document.getElementById('modal-instructions').textContent='Choose a short intention: calm focus, clearer boundaries, or gentle action. Pick one, write it, and repeat it silently for the timer.';
      if(!document.getElementById('intention-input')){
        const inp = document.createElement('input'); inp.id='intention-input'; inp.placeholder='My intention is...'; inp.style.width='100%'; inp.style.marginTop='8px';
        document.getElementById('modal-body').appendChild(inp);
      }
      updateTime();
      timerId = setInterval(()=>{ if(remaining<=0){ stopTimer(); document.getElementById('modal-instructions').textContent='Practice complete. You can keep this intention in mind through the day.'; return; } remaining--; updateTime(); },1000);
    }
    function updateTime(){ const m=Math.floor(remaining/60); const s=remaining%60; timerDisplay.textContent = m+':'+(s<10?'0'+s:s); }
    function stopTimer(){ if(timerId) clearInterval(timerId); timerId=null; }

    // Close modal on backdrop click
    modal.addEventListener('click', (e)=>{ if(e.target===modal) closeModal(); });
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--accent:#276a56;--muted:#586663}
    body{font-family:system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#fbfdfa,#eef6f2);margin:0;color:#0f2b26}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;background:rgba(255,255,255,0.8);border-bottom:1px solid rgba(12,20,18,0.04)}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#0f5f4a);display:flex;align-items:center;justify-content:center;color:white;font-weight:800}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    nav a[href$="about.html"]{color:var(--accent)}
    main{max-width:980px;margin:28px auto;padding:20px}
    .lead{display:grid;grid-template-columns:1fr 300px;gap:18px;align-items:center}
    .card{background:white;padding:16px;border-radius:12px;box-shadow:0 8px 20px rgba(5,12,10,0.04)}
    h1{margin:0;color:var(--accent)}
    .muted{color:var(--muted)}

    .team{display:flex;gap:10px;margin-top:12px}
    .profile{flex:1;padding:12px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#f6faf8)}
    .profile h4{margin:6px 0}

    /* reorder: About page places story after values and then inventory */
    .values{margin-top:18px;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}

    /* small */
    .tiny{font-size:0.9rem;color:var(--muted)}

    /* inventory compact */
    .inventory-compact{margin-top:18px;padding:12px;border-radius:12px;background:linear-gradient(180deg,#fff,#f5fbf7)}
    .checkbox{display:flex;gap:8px;align-items:center}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div class="tiny">Holistic support in {{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Start</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Concerns</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Studio</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="lead">
      <div class="card">
        <h1>Who we are</h1>
        <p class="tiny muted">A small team blending evidence-aware natural approaches, practical habit design, and collaborative planning. Educational and supportive care — not medical guarantees.</p>
        <div class="team">
          <div class="profile">
            <h4>Lead Practitioner</h4>
            <div class="tiny">Credentials in integrative clinical practice, years of experience in whole-person assessment, coaching, and lifestyle design.</div>
          </div>
          <div class="profile">
            <h4>Program Coordinator</h4>
            <div class="tiny">Supports planning, group learning tracks, and client follow-up to keep small practices on track.</div>
          </div>
        </div>
      </div>

      <aside class="card">
        <div style="font-weight:700">Quick connect</div>
        <div style="margin-top:6px" class="tiny">Phone: {{PHONE}}</div>
        <div class="tiny">Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <div style="margin-top:12px"><button onclick="location.href='book.html'" style="padding:8px 10px;border-radius:8px;border:0;background:var(--accent);color:white;cursor:pointer">Book a discovery</button></div>
      </aside>
    </section>

    <section class="values card" aria-label="values">
      <div>
        <h3 style="margin-top:0">Core commitments</h3>
        <div class="tiny muted">We center practical experiments, clear measurement, and collaborative decision-making. Our work is paced to fit the demands of your life.</div>
      </div>
      <div>
        <h3>Education first</h3>
        <div class="tiny muted">We share what we know, why it may help, and simple ways to try it with low burden.</div>
      </div>
      <div>
        <h3>Tailored steps</h3>
        <div class="tiny muted">Plans are composed of small, testable habits and scheduled revisit points to refine progress.</div>
      </div>
    </section>

    <section class="inventory-compact card">
      <h4 style="margin:0">Try a short inventory</h4>
      <div class="tiny muted" style="margin-top:6px">Pick areas you want to address; we produce a short agenda and a follow-up plan you can bring to booking.</div>
      <div style="margin-top:10px">
        <div class="checkbox"><input type="checkbox" id="a1" value="Sleep"><label for="a1"> Sleep</label></div>
        <div class="checkbox"><input type="checkbox" id="a2" value="Energy"><label for="a2"> Energy</label></div>
        <div class="checkbox"><input type="checkbox" id="a3" value="Mood"><label for="a3"> Mood</label></div>
      </div>
      <div style="margin-top:10px"><button onclick="runInventory()" style="padding:8px 10px;border-radius:8px;border:0;background:var(--accent);color:white;cursor:pointer">Generate agenda</button></div>
      <div id="about-agenda" style="margin-top:10px;display:none"></div>
    </section>

    <section class="card" style="margin-top:18px">
      <h3 style="margin-top:0">Our story</h3>
      <p class="muted">{{BUSINESS_NAME}} began as a neighborhood practice focused on translating complex recommendations into small, sustainable trials. Over time we shaped a modest set of session forms and micro-habit supports aimed at steady clarity and fewer surprises.</p>
    </section>

    <section class="card" style="margin-top:18px">
      <h3 style="margin-top:0">Ethical note</h3>
      <p class="tiny muted">We provide education and supportive planning. We do not promise cures; when medical issues are present we coordinate with your primary clinicians for safe, integrated care.</p>
    </section>

  </main>

  <script>
    // reuse inventory logic in compact form
    function runInventory(){
      const boxes = Array.from(document.querySelectorAll('.inventory-compact input[type=checkbox]'));
      const checked = boxes.filter(b=>b.checked).map(b=>b.value);
      const out = document.getElementById('about-agenda');
      if(checked.length===0){ out.style.display='block'; out.textContent='No items selected.'; return; }
      const suggestions = checked.map(item=>'• '+item+': discuss current pattern and 1 small experiment');
      out.style.display='block'; out.textContent = suggestions.join('\n') + '\nRecommended follow-up: '+(checked.length>2? 'Biweekly initial':'Monthly or biweekly depending on interest');
    }
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#1f6e56;--muted:#556b66;--bg:#f8fcfb}
    body{font-family:system-ui,Segoe UI,Roboto,Arial;background:var(--bg);margin:0;color:#07261f}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;background:white;border-bottom:1px solid rgba(6,10,8,0.04)}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{max-width:920px;margin:28px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:white;padding:16px;border-radius:12px;box-shadow:0 10px 28px rgba(8,12,10,0.04)}
    h1{margin:0;color:var(--accent)}
    .muted{color:var(--muted)}
    label{display:block;margin-top:10px}
    input,select,textarea{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid #e6efea}
    .btn{background:var(--accent);color:white;padding:10px 12px;border:0;border-radius:8px;cursor:pointer;margin-top:12px}

    /* booking includes the whole-person inventory + scheduling cadence derived */
    .summary{margin-top:12px;padding:10px;border-radius:10px;background:linear-gradient(180deg,#fff,#f5fdf9)}
    .tiny{font-size:0.9rem;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:10px;align-items:center">
      <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#0f5f4a);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700">HB</div>
      <div>{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Start</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Concerns</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Studio</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <div class="card">
          <h1>Reserve a session</h1>
          <p class="muted">Choose a session type and tell us a few priorities. We'll use your responses to create a focused agenda for our time together.</p>

          <form id="booking-form" onsubmit="event.preventDefault();submitBooking();">
            <label>Session type</label>
            <select id="session-type">
              <option value="intro">Intro Insight — 60m</option>
              <option value="package">Care Plan Package — series</option>
              <option value="mini">Focused Mini — 45m</option>
            </select>

            <label>Primary concern (short)</label>
            <input id="primary" placeholder="e.g., low energy, sleep trouble, digestion" required />

            <label>When does this matter most?</label>
            <input id="when" placeholder="e.g., mornings, after work, weekend" />

            <label>Contact email</label>
            <input id="email" type="email" value="{{EMAIL}}" />

            <div style="margin-top:12px">
              <div class="tiny">Optional: quick inventory — check areas you'd like the practitioner to prioritize for your agenda</div>
              <div style="margin-top:8px;display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px">
                <label><input type="checkbox" value="Sleep"/> Sleep</label>
                <label><input type="checkbox" value="Energy"/> Energy</label>
                <label><input type="checkbox" value="Mood"/> Mood</label>
                <label><input type="checkbox" value="Gut"/> Digestion</label>
                <label><input type="checkbox" value="Movement"/> Movement</label>
                <label><input type="checkbox" value="Work"/> Work</label>
                <label><input type="checkbox" value="Relationships"/> Relationships</label>
                <label><input type="checkbox" value="Purpose"/> Meaning</label>
              </div>
            </div>

            <button type="submit" class="btn">Request this time</button>
          </form>

          <div id="booking-summary" class="summary" style="display:none"></div>
        </div>

        <div class="card" style="margin-top:14px">
          <h3 style="margin:0">What happens next</h3>
          <div class="tiny muted" style="margin-top:8px">After you request a time we send a short confirmation and a pre-visit intake that outlines the agenda and recommended check-ins. Sessions are educational and voluntary.</div>
        </div>

      </div>

      <aside>
        <div class="card">
          <h4 style="margin:0">Reserve support</h4>
          <div class="tiny" style="margin-top:8px">If you prefer, call: {{PHONE}}</div>
          <div style="margin-top:10px"><button onclick="location.href='contact.html'" class="btn">Message us</button></div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0">Quick clarity tool</h4>
          <div class="tiny" style="margin-top:8px">Not ready to book? Try a guided 3-minute practice to center priorities.</div>
          <div style="margin-top:10px"><button onclick="openModal()" class="btn">Start the 3-minute exercise</button></div>
        </div>
      </aside>
    </div>
  </main>

  <script>
    // booking + local agenda generation (reuses inventory mapping)
    const mapping = {
      'Sleep': ['Review sleep schedule and 1 actable change'],
      'Energy': ['Map daily energy swings and plan small renewals'],
      'Mood': ['Short stress-response tools and journaling prompts'],
      'Gut': ['Dietary timing review and simple experiments'],
      'Movement': ['Functional movement quick check and plan'],
      'Relationships': ['Boundary review and short communication tools'],
      'Work': ['Workload triage and scheduling strategy'],
      'Purpose': ['Values check and micro-experiments']
    };

    function submitBooking(){
      const type = document.getElementById('session-type').value;
      const primary = document.getElementById('primary').value;
      const when = document.getElementById('when').value;
      const email = document.getElementById('email').value || '{{EMAIL}}';
      const checks = Array.from(document.querySelectorAll('form input[type=checkbox]')).filter(c=>c.checked).map(c=>c.value);

      // build agenda
      let agendaItems = [];
      if(checks.length>0) agendaItems = checks.map(c=> (mapping[c] ? (c+': '+mapping[c]) : (c+': Listening and tailored steps')) );
      else agendaItems = ['Full intake: history, priorities, and 1-2 initial experiments'];

      // cadence suggestion based on complexity
      let cadence = '';
      if(checks.length===0) cadence='Follow-up suggestion: 1 session, revisit in 3-6 weeks.';
      else if(checks.length<=2) cadence='Follow-up suggestion: 1-2 sessions across 4-8 weeks.';
      else cadence='Follow-up suggestion: Biweekly contact for 8-12 weeks with brief check-ins.';

      const summary = document.getElementById('booking-summary');
      summary.style.display='block';
      summary.innerHTML = '<strong>Requested:</strong> '+(type==='intro'?'Intro Insight — 60m': type==='package'?'Care Plan Package':'Focused Mini') + '<br>'+
                          '<strong>Primary concern:</strong> '+escapeHtml(primary)+'<br>'+
                          (when?('<strong>Timing:</strong> '+escapeHtml(when)+'<br>'):'')+
                          '<strong>Email:</strong> '+escapeHtml(email)+'<br><br>'+
                          '<strong>Planned agenda:</strong><br>' + agendaItems.join('<br>') + '<br><br>'+
                          '<strong>'+cadence+'</strong>' + '<div style="margin-top:8px" class="tiny">We will follow up to confirm scheduling and ask a few brief intake questions before the visit.</div>';

      // pretend to send request (in real site we'd POST to backend)
      alert('Request created locally. In a production site this would be sent to {{BUSINESS_NAME}} for scheduling.');
      // optionally prefill fields for follow-up
      // save to localStorage for convenience
      localStorage.setItem('lastBooking', JSON.stringify({type,primary,when,checks,email,agenda:agendaItems,cadence}));
    }

    function escapeHtml(s){ return String(s).replace(/[&<>"']/g, function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]; }); }

    // Guided practice modal (embedded minimal)
    function openModal(){
      // simple inline modal: reuse the small practice used on pricing but built here inline to satisfy requirement
      const modal = document.createElement('div'); modal.style.position='fixed'; modal.style.inset='0'; modal.style.background='rgba(6,12,10,0.28)'; modal.style.display='flex'; modal.style.alignItems='center'; modal.style.justifyContent='center';
      const card = document.createElement('div'); card.style.background='white'; card.style.padding='18px'; card.style.borderRadius='12px'; card.style.maxWidth='600px'; card.style.width='100%';
      card.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center"><strong>3-minute practice</strong><button id="closeLocal">Close</button></div>';
      const body = document.createElement('div'); body.style.marginTop='10px';
      body.innerHTML = '<div style="display:flex;gap:12px;align-items:center"><div style="width:72px;height:72px;border-radius:50%;background:linear-gradient(180deg,#f8fff9,#e6f7ef);display:flex;align-items:center;justify-content:center;font-weight:700">3:00</div><div style="flex:1">Pick: <button id="bbtn">Breathing</button> <button id="jbtn">Journal</button> <button id="ibtn">Intention</button></div></div><div id="local-instructions" style="margin-top:10px" class="tiny"></div>';
      card.appendChild(body); modal.appendChild(card); document.body.appendChild(modal);

      let timer = null; let remain = 180; const display = card.querySelector('div > div > div');
      function update(){ const m=Math.floor(remain/60); const s=remain%60; display.textContent = m+':'+(s<10?'0'+s:s); }
      function stop(){ if(timer) clearInterval(timer); timer=null; }
      function start(type){ stop(); remain=180; update(); const instr = card.querySelector('#local-instructions'); instr.textContent=''; if(type==='b'){ instr.textContent='Breathe: inhale 4s, hold 3s, exhale 5s. Follow the rhythm.'; }
        if(type==='j'){ instr.innerHTML='Prompt: "What small step would make the biggest difference this week?" <textarea id="local-ta" style="width:100%;height:90px;margin-top:8px"></textarea>'; }
        if(type==='i'){ instr.innerHTML='Write a short intention below: <input id="local-i" style="width:100%;margin-top:8px" placeholder="My intention is...">'; }
        timer = setInterval(()=>{ if(remain<=0){ stop(); instr.textContent='Done. Carry this forward.'; return; } remain--; update(); },1000);
      }
      card.querySelector('#bbtn').addEventListener('click',()=>start('b'));
      card.querySelector('#jbtn').addEventListener('click',()=>start('j'));
      card.querySelector('#ibtn').addEventListener('click',()=>start('i'));
      card.querySelector('#closeLocal').addEventListener('click',()=>{ stop(); document.body.removeChild(modal); });
    }
  </script>
</body>
</html>"} 
